package domain

import "time"

// An Operation is one queued change from a client that was offline. The PWA
// appends them to IndexedDB while there is no network and posts the batch to
// POST /api/sync when there is (00-scope.md §5, 01-structure.md §1.5).
//
// OpID is generated by the client and is what makes a resend harmless: the
// server records the ids it has already applied, and a phone that lost signal
// mid-POST can send the whole batch again without duplicating anything.
type Operation struct {
	OpID string
	Type OpType
	At   time.Time

	// Payload is one of the *Payload types below, matching Type. The domain
	// declares the shapes; decoding JSON into them is the adapter's job.
	Payload any
}

// OpType enumerates what a queued operation can be. The set is closed: an
// unknown type is a client programming error, not a business case.
type OpType string

const (
	OpBoardCreate   OpType = "board.create"
	OpBoardUpdate   OpType = "board.update"
	OpBoardDelete   OpType = "board.delete"
	OpColumnCreate  OpType = "column.create"
	OpColumnUpdate  OpType = "column.update"
	OpColumnDelete  OpType = "column.delete"
	OpColumnReorder OpType = "column.reorder"
	OpCardCreate    OpType = "card.create"
	OpCardUpdate    OpType = "card.update"
	OpCardDelete    OpType = "card.delete"
	OpCardMove      OpType = "card.move"
)

// KnownOpType reports whether t is one this server can apply.
func KnownOpType(t OpType) bool {
	switch t {
	case OpBoardCreate, OpBoardUpdate, OpBoardDelete,
		OpColumnCreate, OpColumnUpdate, OpColumnDelete, OpColumnReorder,
		OpCardCreate, OpCardUpdate, OpCardDelete, OpCardMove:
		return true
	}
	return false
}

// Payload shapes, one per OpType.
type (
	BoardCreatePayload struct {
		ID   string
		Name string
	}
	BoardUpdatePayload struct {
		ID   string
		Name *string
	}
	BoardDeletePayload struct {
		ID string
	}
	ColumnCreatePayload struct {
		ID       string
		BoardID  string
		Name     string
		WIPLimit *int
	}
	ColumnUpdatePayload struct {
		ID    string
		Patch ColumnPatch
	}
	ColumnDeletePayload struct {
		ID string
	}
	ColumnReorderPayload struct {
		BoardID string
		IDs     []string
	}
	CardCreatePayload struct {
		ID          string
		ColumnID    string
		Title       string
		Description string
		Label       string
	}
	CardUpdatePayload struct {
		ID    string
		Patch CardPatch
	}
	CardDeletePayload struct {
		ID string
	}
	CardMovePayload struct {
		ID         string
		ToColumnID string
		ToIndex    int
	}
)

// OpStatus is the outcome of a single operation inside a batch. A batch never
// fails as a whole because of one bad entry: twenty queued changes collapsing
// over one would leave the user stuck on their phone (02-testing.md §4.5).
type OpStatus string

const (
	// OpApplied: the operation changed the server state.
	OpApplied OpStatus = "applied"
	// OpDuplicate: this op_id was already applied. Nothing happened, and that
	// is the correct outcome, not an error.
	OpDuplicate OpStatus = "duplicate"
	// OpFailed: a rule refused it. State holds the server's version so the
	// client can correct itself.
	OpFailed OpStatus = "failed"
	// OpConflict: the server's copy is newer. Last-write-wins says the server
	// keeps its value (00-scope.md §6.5) and returns it.
	OpConflict OpStatus = "conflict"
)

// OpResult reports what happened to one operation.
type OpResult struct {
	OpID   string
	Status OpStatus
	// Code is the machine-readable reason for failed and conflict:
	// "wip_exceeded", "not_found", "invalid", "column_not_empty".
	Code string
	// Message is for a human reading logs, never for a switch statement.
	Message string
	// State is the server's current version of the affected entity
	// (*Board, *Column or *Card), so the client can reconcile without a
	// second round trip. Nil when there is nothing useful to send back.
	State any
}
